"""All-or-nothing changes across one or more in-memory repositories.

    with UnitOfWork(payments, orders):
        ...  # any exception restores every repository to its state on entry

Inserts, updates (including objects changed in place) and deletes are all
undone on rollback. The exception is re-raised.
"""


class UnitOfWork:
    def __init__(self, *repositories):
        self.repositories = repositories
        self._states = []

    def __enter__(self):
        self._states = [(repo, repo.snapshot()) for repo in self.repositories]
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type is not None:
            for repo, state in reversed(self._states):
                repo.restore(state)
        self._states = []
        return False

