def __len__(self) -> int:
    return len(self._items)

# -- transactions ------------------------------------------------------
def snapshot(self):
    """Capture enough state to undo every change made after this call."""
    return dict(self._items), self._counter

def restore(self, state) -> None:
    items, counter = state
    self._items = dict(items)
    self._counter = counter
